// ============================================================================
// TRNG_apb: APB4 register wrapper around TRNG_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/TRNG.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/TRNG.md
// ============================================================================
module TRNG_apb #(
  parameter int NRO = 4,
  parameter int APT_WL = 10
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic [NRO-1:0] ro_in,
  output logic ent_fips,
  output logic raw_valid,
  output logic raw_bit,
  output logic es_ok,
  output logic alert
);
  localparam logic [31:0] ID_VALUE = 32'h54520100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [11:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd12) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_en;
  logic          c_src_sel;
  logic          c_cond_bypass;
  logic [1:0]    c_cond_blks;
  logic [7:0]    c_smp_div;
  logic [7:0]    c_rct_cutoff;
  logic [10:0]   c_apt_cutoff;
  logic [31:0]   c_lfsr_seed;
  logic          c_ent_valid;
  logic          c_ent_ready;
  logic [31:0]   c_ent_data;
  logic          c_seed_rdy;
  logic [2:0]    c_state;
  logic          c_es_ok;
  logic          c_es_fips;
  logic          c_alert;
  logic          c_alert_rct;
  logic          c_alert_apt;
  logic [7:0]    c_rct_fails;
  logic [7:0]    c_apt_fails;
  logic [7:0]    c_rct_hw;
  logic [10:0]   c_apt_hw;
  TRNG_top #(.NRO(NRO), .APT_WL(APT_WL)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .ro_in(ro_in),
    .en(c_en),
    .src_sel(c_src_sel),
    .cond_bypass(c_cond_bypass),
    .cond_blks(c_cond_blks),
    .smp_div(c_smp_div),
    .rct_cutoff(c_rct_cutoff),
    .apt_cutoff(c_apt_cutoff),
    .lfsr_seed(c_lfsr_seed),
    .ent_valid(c_ent_valid),
    .ent_ready(c_ent_ready),
    .ent_data(c_ent_data),
    .ent_fips(ent_fips),
    .seed_rdy(c_seed_rdy),
    .raw_valid(raw_valid),
    .raw_bit(raw_bit),
    .state(c_state),
    .es_ok(c_es_ok),
    .es_fips(c_es_fips),
    .alert(c_alert),
    .alert_rct(c_alert_rct),
    .alert_apt(c_alert_apt),
    .rct_fails(c_rct_fails),
    .apt_fails(c_apt_fails),
    .rct_hw(c_rct_hw),
    .apt_hw(c_apt_hw)
  );
  assign alert = c_alert;  // also readable in the registers
  assign es_ok = c_es_ok;  // also readable in the registers

  // ---------------- registers ----------------
  logic [2:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [12:0] r_CTRL;   // 12'h014 CTRL
  logic [18:0] r_HEALTH;   // 12'h018 HEALTH
  logic [31:0] r_LFSR_SEED;   // 12'h01C LFSR_SEED
  logic [31:0] h_ENT;   // 12'h020 ENT holding register
  logic avail_ENT;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 13'h8;
      r_HEALTH <= 19'h31929;
      r_LFSR_SEED <= 32'h1;
      h_ENT <= '0;
      avail_ENT <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[2:0] & wmask[2:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[2:0]) | (PWDATA[2:0] & wmask[2:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[12:0]) | (PWDATA[12:0] & wmask[12:0]);
      if (wr && hit[6]) r_HEALTH <= (r_HEALTH & ~wmask[18:0]) | (PWDATA[18:0] & wmask[18:0]);
      if (wr && hit[7]) r_LFSR_SEED <= (r_LFSR_SEED & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (c_ent_valid && (!avail_ENT || (rd && hit[8]))) begin
        h_ENT[31:0] <= c_ent_data[31:0];
        avail_ENT <= 1'b1;
      end else if (rd && hit[8]) avail_ENT <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_en = r_CTRL[0:0];
  assign c_src_sel = r_CTRL[1:1];
  assign c_cond_bypass = r_CTRL[2:2];
  assign c_cond_blks = r_CTRL[4:3];
  assign c_smp_div = r_CTRL[12:5];
  assign c_rct_cutoff = r_HEALTH[7:0];
  assign c_apt_cutoff = r_HEALTH[18:8];
  assign c_lfsr_seed = r_LFSR_SEED[31:0];
  assign c_ent_ready = ~avail_ENT | (rd & hit[8]);

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_seed_rdy;
    irq_set[1] = c_alert;
    irq_set[2] = c_ent_valid & (~avail_ENT | (rd & hit[8]));
  end
  assign irq = |(irq_status & irq_enable);
  wire [0:0] flags = {avail_ENT};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CTRL);
      10'd6: apb_rdata = 32'(r_HEALTH);
      10'd7: apb_rdata = 32'(r_LFSR_SEED);
      10'd8: apb_rdata = 32'(h_ENT);
      10'd9: apb_rdata = 32'({c_alert_apt, c_alert_rct, c_es_fips, c_es_ok, c_state});
      10'd10: apb_rdata = 32'({c_apt_fails, c_rct_fails});
      10'd11: apb_rdata = 32'({c_apt_hw, c_rct_hw});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
